for bi, (ename, theme, note, titles) in enumerate(BATCHES):
    assert len(titles) == 20, ename
    f1 = 901 + bi * 20
    f2 = f1 + 19
    lines = []
    lines.append(f"#### UNX-E4-{ename} · {theme}（UNX-E4-E{f1:03d}–E{f2:03d} · 20 条）")
    lines.append("")
    lines.append(f"> AI-24 承办｜增补卷四（独立编号不占域账，紧接卷三零跳号 E901 起，判例承 AI-27/AI-29/AI-15/AI-19）｜域账累计：不占（增补卷独立计量，F19189 封账宣示不破）｜嫁接源：E4 域 B01–B40 全部产物为承接契约；卷一 E01–E15/卷二 E16–E30/卷三 E31–E45 依赖面见各批互证挂点｜防重：与 B01–B40、E01–E45 分层——本批管「{note[:36]}」；主题聚类对全域判据对表嫌疑=空｜批注：{note}｜状态列统一「增补」不冒充深化｜红线声明：涉写盘条目一律三重验证+dry-run+原子写；无引导类条目")
    lines.append("")
    lines.append("| 编号 | 功能条目 | 行数 | 状态 | 判据 |")
    lines.append("|---|---|---|---|---|")
    for i, title in enumerate(titles):
        fid = f1 + i
        eid = f"UNX-E4-E{fid:03d}"
